using System;
using System.Collections.Generic;

public sealed class EventChannel<T>
{
    // 구독 하나 = 객체 하나. 해지 토큰을 겸한다.
    private sealed class Subscription : IDisposable
    {
        public EventChannel<T> Owner;
        public Action<T> Handler;
        public bool Active = true;

        public void Dispose()
        {
            if (!Active) return;            // 두 번째 Dispose 부터는 무시
            Active = false;
            EventChannel<T> owner = Owner;
            Owner = null;
            Handler = null;                 // 구독자 객체를 더 붙잡지 않는다
            owner.OnDisposed(this);
        }
    }

    // 캡처가 없는 정적 메서드로 만든 델리게이트를 한 번만 만들어 재사용한다.
    private static readonly Predicate<Subscription> IsInactive = IsInactiveImpl;
    private static bool IsInactiveImpl(Subscription s) { return !s.Active; }

    private readonly List<Subscription> _subs = new List<Subscription>();
    private int _liveCount;
    private int _publishDepth;              // 진행 중인 Publish 의 중첩 깊이
    private bool _needsCompaction;          // 순회 중 해지되어 목록에 남은 칸이 있는가

    public int SubscriberCount
    {
        get { return _liveCount; }
    }

    public IDisposable Subscribe(Action<T> handler)
    {
        if (handler == null) throw new ArgumentNullException(nameof(handler));
        Subscription s = new Subscription { Owner = this, Handler = handler };
        _subs.Add(s);                       // 항상 맨 뒤: 진행 중인 Publish 의 범위(count) 밖
        _liveCount++;
        return s;
    }

    public void Publish(T payload)
    {
        int count = _subs.Count;            // 이 Publish 가 시작될 때 있던 구독까지만 본다
        _publishDepth++;
        try
        {
            for (int i = 0; i < count; i++)
            {
                Subscription s = _subs[i];
                if (!s.Active) continue;    // 자기 차례 전에 해지된 구독은 건너뛴다
                s.Handler(payload);
            }
        }
        finally
        {
            _publishDepth--;
            if (_publishDepth == 0 && _needsCompaction)
            {
                _needsCompaction = false;
                _subs.RemoveAll(IsInactive);
            }
        }
    }

    private void OnDisposed(Subscription s)
    {
        _liveCount--;
        if (_publishDepth > 0)
        {
            _needsCompaction = true;        // 순회 중: 인덱스를 흔들지 않고 표시만 해 둔다
        }
        else
        {
            _subs.Remove(s);
        }
    }
}

