        {
            var ch = new EventChannel<int>();
            var log = new System.Collections.Generic.List<string>();
            System.IDisposable ta = null;
            ta = ch.Subscribe(v => { log.Add("A" + v); if (v == 1) ch.Publish(2); });
            ch.Subscribe(v => { log.Add("B" + v); if (v == 2) ta.Dispose(); });
            ch.Subscribe(v => log.Add("C" + v));
            ch.Publish(1);
            string e = Expect(log, "A1 A2 B2 C2 B1 C1", "중첩 Publish 안에서 A 가 해지된 뒤 바깥 Publish 가 이어지는 순서");
            if (e != null) return e;
            log.Clear(); ch.Publish(3);
            e = Expect(log, "B3 C3", "중첩 Publish 가 끝난 뒤");
            if (e != null) return e;
            return ch.SubscriberCount == 2 ? null : "SubscriberCount 기대 2, 결과 " + ch.SubscriberCount;
        });

        Run("no-alloc-publish", () =>
        {
            var ch = new EventChannel<int>();
            long sum = 0;
            var tokens = new System.IDisposable[8];
            for (int i = 0; i < 8; i++) tokens[i] = ch.Subscribe(v => sum += v);
            tokens[3].Dispose();
            for (int i = 0; i < 300; i++) ch.Publish(i);
            long before = System.GC.GetAllocatedBytesForCurrentThread();
            for (int i = 0; i < 5000; i++) ch.Publish(1);
            long bytes = System.GC.GetAllocatedBytesForCurrentThread() - before;
            if (sum != 7L * (299 * 300 / 2) + 7L * 5000) return "호출 횟수가 맞지 않음 (합계 " + sum + ")";
            return bytes == 0 ? null : "구독 변화가 없는 Publish 5000회 동안 " + bytes + "바이트 할당됨 (매번 목록을 복사하고 있지 않은가?)";
        });

        Run("random-vs-reference", () =>
        {
            // 구독 k 는 호출될 때 act[k] 에 따라 행동한다: -1 없음, -2 새 구독 하나 추가(1회), j >= 0 구독 j 해지
            var rng = new System.Random(20240);
            for (int round = 0; round < 300; round++)
            {
                var ch = new EventChannel<int>();
                var log = new System.Collections.Generic.List<string>();
                var refLog = new System.Collections.Generic.List<string>();
                var tokens = new System.Collections.Generic.List<System.IDisposable>();
                var act = new System.Collections.Generic.List<int>();
                System.Action<int> add = null;
                add = a =>
                {
                    int k = tokens.Count;
                    act.Add(a); tokens.Add(null);
                    tokens[k] = ch.Subscribe(v =>
                    {
                        log.Add(k + ":" + v);
                        if (act[k] == -2) { act[k] = -1; add(-1); }
                        else if (act[k] >= 0) tokens[act[k]].Dispose();
                    });
                };
                int n0 = rng.Next(2, 7);
                for (int i = 0; i < n0; i++) { int r = rng.Next(10); add(r < 4 ? -1 : r < 6 ? -2 : rng.Next(n0)); }
                var refAct = new System.Collections.Generic.List<int>(act);
                var alive = new System.Collections.Generic.List<bool>();
                for (int i = 0; i < n0; i++) alive.Add(true);
                for (int p = 0; p < 3; p++)
                {
                    ch.Publish(p);
                    int snapshot = alive.Count;
                    for (int k = 0; k < snapshot; k++)
                    {
                        if (!alive[k]) continue;
                        refLog.Add(k + ":" + p);
                        if (refAct[k] == -2) { refAct[k] = -1; refAct.Add(-1); alive.Add(true); }
                        else if (refAct[k] >= 0) alive[refAct[k]] = false;
                    }
                    int live = 0;
                    foreach (bool x in alive) if (x) live++;
                    string got = string.Join(" ", log), exp = string.Join(" ", refLog);
                    if (got != exp) return "라운드 " + round + ", Publish(" + p + ") 뒤 (구독번호:값): 기대 [" + exp + "], 결과 [" + got + "]";
                    if (ch.SubscriberCount != live) return "라운드 " + round + ": SubscriberCount 기대 " + live + ", 결과 " + ch.SubscriberCount;
                }
            }
            return null;
        });
    }
}

