public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // 훅 호출을 기록하고, 테스트가 꽂아 둔 동작을 실행하는 상태
    sealed class Rec : IState
    {
        public CharState Id;
        public System.Collections.Generic.List<string> Log;
        public System.Action<CharacterFsm> OnEnter, OnUpdate, OnExit;
        public void Enter(CharacterFsm f) { Log.Add("Enter:" + Id); if (OnEnter != null) OnEnter(f); }
        public void Update(CharacterFsm f, float dt) { Log.Add("Update:" + Id); if (OnUpdate != null) OnUpdate(f); }
        public void Exit(CharacterFsm f) { Log.Add("Exit:" + Id); if (OnExit != null) OnExit(f); }
    }

    static readonly CharState[] Registered = { CharState.Idle, CharState.Move, CharState.Attack, CharState.Stunned };
    // 허용 전이 (from, to) 쌍을 평평하게 나열
    static readonly int[] Table =
    {
        0, 1,  0, 2,  1, 0,  1, 2,  2, 0,  2, 2,
        0, 3,  1, 3,  2, 3,  3, 0,  0, 4
    };

    sealed class Rig
    {
        public CharacterFsm F = new CharacterFsm();
        public System.Collections.Generic.List<string> Log = new System.Collections.Generic.List<string>();
        public System.Collections.Generic.Dictionary<CharState, Rec> S = new System.Collections.Generic.Dictionary<CharState, Rec>();
        public Rig()
        {
            foreach (CharState id in Registered) { var r = new Rec { Id = id, Log = Log }; S[id] = r; F.AddState(id, r); }
            for (int i = 0; i < Table.Length; i += 2) F.AllowTransition((CharState)Table[i], (CharState)Table[i + 1]);
        }
        public string Expect(string expected, string what)
        {
            string got = string.Join(" ", Log);
            return got == expected ? null : what + ": 기대 [" + expected + "], 결과 [" + got + "]";
        }
    }

    static bool Throws<TEx>(System.Action a) where TEx : System.Exception
    {
        try { a(); } catch (TEx) { return true; } catch (System.Exception) { return false; }
        return false;
    }

    public static void Main()
    {
        Run("start-and-update", () =>
        {
            var r = new Rig();
            r.F.Start(CharState.Idle);
            string e = r.Expect("Enter:Idle", "Start 직후");
            if (e != null) return e;
            if (r.F.Current != CharState.Idle) return "Current 기대 Idle, 결과 " + r.F.Current;
            r.F.Update(0.016f); r.F.Update(0.016f);
            return r.Expect("Enter:Idle Update:Idle Update:Idle", "Update 두 번 뒤");
        });

        Run("transition-order", () =>
        {
            var r = new Rig();
            r.F.Start(CharState.Idle);
            r.S[CharState.Idle].OnExit = f => r.Log.Add("cur=" + f.Current);
            r.S[CharState.Move].OnEnter = f => r.Log.Add("cur=" + f.Current);
            r.Log.Clear();
            if (!r.F.RequestTransition(CharState.Move)) return "허용된 전이 Idle -> Move 가 false 를 반환";
            string e = r.Expect("Exit:Idle cur=Idle Enter:Move cur=Move", "Idle -> Move (Exit 가 먼저, 훅 안의 Current 확인)");
            if (e != null) return e;
            if (r.F.Current != CharState.Move) return "전이 후 Current 기대 Move, 결과 " + r.F.Current;
            r.Log.Clear();
            r.F.RequestTransition(CharState.Attack); r.F.RequestTransition(CharState.Attack);
            return r.Expect("Exit:Move Enter:Attack Exit:Attack Enter:Attack", "Move -> Attack 뒤 테이블에 있는 자기 전이 Attack -> Attack");
        });

        Run("invalid-rejected", () =>
        {
            var r = new Rig();
            r.F.Start(CharState.Idle);
            r.F.RequestTransition(CharState.Stunned);
            r.Log.Clear();
            if (r.F.RequestTransition(CharState.Attack)) return "테이블에 없는 Stunned -> Attack 이 true 를 반환";
            if (r.F.RequestTransition(CharState.Stunned)) return "테이블에 없는 자기 전이 Stunned -> Stunned 가 true 를 반환";
            if (r.Log.Count != 0) return "거절된 전이에서 훅이 호출됨: [" + string.Join(" ", r.Log) + "]";
            if (r.F.Current != CharState.Stunned) return "거절 후 Current 가 바뀜: " + r.F.Current;
            r.F.RequestTransition(CharState.Idle);
            r.Log.Clear();
            if (r.F.RequestTransition(CharState.Dead)) return "테이블에는 있지만 등록되지 않은 상태(Dead)로의 전이가 true 를 반환";
            if (r.Log.Count != 0 || r.F.Current != CharState.Idle) return "등록되지 않은 상태로의 요청이 상태나 훅에 영향을 줌";
            return null;
        });

        Run("deferred-in-update", () =>
        {
            var r = new Rig();
            r.F.Start(CharState.Idle);
            r.F.RequestTransition(CharState.Move);
            r.S[CharState.Move].OnUpdate = f =>
            {
                bool ok = f.RequestTransition(CharState.Attack);
                r.Log.Add("req=" + ok + ",cur=" + f.Current);
            };
            r.Log.Clear();
            r.F.Update(0.016f);
            string e = r.Expect("Update:Move req=True,cur=Move Exit:Move Enter:Attack",
                "Update 안에서 요청한 전이는 그 Update 가 끝난 뒤, fsm.Update 반환 전에 적용 (새 상태의 Update 는 이번 프레임에 호출 안 함)");
            if (e != null) return e;
            return r.F.Current == CharState.Attack ? null : "Update 반환 후 Current 기대 Attack, 결과 " + r.F.Current;
        });

        Run("chain-from-enter", () =>
        {
            var r = new Rig();
            r.F.Start(CharState.Idle);
            r.F.RequestTransition(CharState.Stunned);
            r.S[CharState.Stunned].OnUpdate = f => f.RequestTransition(CharState.Idle);
            r.S[CharState.Idle].OnEnter = f => { f.RequestTransition(CharState.Move); r.Log.Add("EnterDone:Idle"); };
            r.Log.Clear();
            r.F.Update(0.5f);
            string e = r.Expect("Update:Stunned Exit:Stunned Enter:Idle EnterDone:Idle Exit:Idle Enter:Move",
                "Enter 안에서 요청한 전이는 그 Enter 가 끝난 뒤에 이어서 적용");
            if (e != null) return e;
            return r.F.Current == CharState.Move ? null : "Current 기대 Move, 결과 " + r.F.Current;
        });

        Run("multi-request-validation", () =>
        {
            var r = new Rig();
            r.F.Start(CharState.Idle);
            r.S[CharState.Idle].OnUpdate = f =>
            {
                bool a = f.RequestTransition(CharState.Move);      // Idle -> Move : 허용
                bool b = f.RequestTransition(CharState.Stunned);   // Move -> Stunned : 허용
                bool c = f.RequestTransition(CharState.Attack);    // Stunned -> Attack : 거절
                r.Log.Add(a + "," + b + "," + c);
            };
            r.Log.Clear();
            r.F.Update(0.016f);
            string e = r.Expect("Update:Idle True,True,False Exit:Idle Enter:Move Exit:Move Enter:Stunned",
                "한 훅에서 여러 번 요청: 각 요청은 앞선 요청이 적용된 뒤의 상태를 기준으로 검증");
            if (e != null) return e;
            return r.F.Current == CharState.Stunned ? null : "Current 기대 Stunned, 결과 " + r.F.Current;
        });

        Run("api-misuse", () =>
        {
            var f = new CharacterFsm();
            var log = new System.Collections.Generic.List<string>();
            f.AddState(CharState.Idle, new Rec { Id = CharState.Idle, Log = log });
            if (!Throws<System.InvalidOperationException>(() => f.Update(0.1f))) return "Start 전 Update 가 InvalidOperationException 을 던지지 않음";
            if (!Throws<System.InvalidOperationException>(() => f.RequestTransition(CharState.Idle))) return "Start 전 RequestTransition 이 InvalidOperationException 을 던지지 않음";
            if (!Throws<System.ArgumentException>(() => f.AddState(CharState.Idle, new Rec { Id = CharState.Idle, Log = log }))) return "같은 상태를 두 번 AddState 해도 ArgumentException 이 없음";
            if (!Throws<System.ArgumentNullException>(() => f.AddState(CharState.Move, null))) return "AddState(null) 이 ArgumentNullException 을 던지지 않음";
            if (!Throws<System.InvalidOperationException>(() => f.Start(CharState.Attack))) return "등록되지 않은 상태로 Start 해도 InvalidOperationException 이 없음";
            if (log.Count != 0) return "실패한 호출에서 훅이 불림: [" + string.Join(" ", log) + "]";
            f.Start(CharState.Idle);
            if (!Throws<System.InvalidOperationException>(() => f.Start(CharState.Idle))) return "Start 를 두 번 호출해도 InvalidOperationException 이 없음";
            return string.Join(" ", log) == "Enter:Idle" ? null : "Enter 는 정확히 한 번이어야 함: [" + string.Join(" ", log) + "]";
        });

        Run("request-in-exit", () =>
        {
            var r = new Rig();
            r.F.Start(CharState.Idle);
            bool asked = false;
            r.S[CharState.Idle].OnExit = f =>
            {
                if (asked) return;
                asked = true;
                bool ok = f.RequestTransition(CharState.Idle);     // 기준은 이미 수락된 목적지 Move: Move -> Idle 허용
                r.Log.Add("req=" + ok + ",cur=" + f.Current);
            };
            r.Log.Clear();
            r.F.RequestTransition(CharState.Move);
            string e = r.Expect("Exit:Idle req=True,cur=Idle Enter:Move Exit:Move Enter:Idle",
                "Idle -> Move 전이의 Exit(Idle) 안에서 Idle 요청: 검증 기준은 진행 중인 전이의 목적지 Move (Move -> Idle 은 허용)");
            if (e != null) return e;
            if (r.F.Current != CharState.Idle) return "Current 기대 Idle, 결과 " + r.F.Current;
            r.F.RequestTransition(CharState.Stunned);
            r.S[CharState.Stunned].OnExit = f => r.Log.Add("req=" + f.RequestTransition(CharState.Idle));   // 기준 Idle: Idle -> Idle 은 테이블에 없음
            r.Log.Clear();
            r.F.RequestTransition(CharState.Idle);
            e = r.Expect("Exit:Stunned req=False Enter:Idle",
                "Stunned -> Idle 전이의 Exit(Stunned) 안에서 Idle 요청: 기준은 목적지 Idle 이므로 Idle -> Idle (테이블에 없음) 은 거절");
            if (e != null) return e;
            return r.F.Current == CharState.Idle ? null : "Current 기대 Idle, 결과 " + r.F.Current;
        });

        Run("random-vs-reference", () =>
        {
            // 훅이 불릴 때마다 미리 뽑아 둔 결정 dec[n] 을 차례로 소비한다: -1 요청 없음, 그 외는 요청할 상태
            var rng = new System.Random(4242);
            for (int round = 0; round < 200; round++)
            {
                int[] dec = new int[400];
                for (int i = 0; i < dec.Length; i++) dec[i] = rng.Next(100) < 30 ? rng.Next(5) : -1;
                int[] ops = new int[25];
                for (int i = 0; i < ops.Length; i++) ops[i] = rng.Next(100) < 50 ? -1 : rng.Next(5);

                var r = new Rig();
                int n = 0;
                System.Action<CharacterFsm> hook = f =>
                {
                    int d = n < dec.Length ? dec[n] : -1; n++;
                    if (d >= 0) r.Log.Add((f.RequestTransition((CharState)d) ? "+" : "-") + (CharState)d);
                };
                foreach (var s in r.S.Values) { s.OnEnter = hook; s.OnUpdate = hook; s.OnExit = hook; }

                // 참조 모델
                var mlog = new System.Collections.Generic.List<string>();
                var q = new System.Collections.Generic.Queue<int>();
                int cur = 0, logical = 0, m = 0;
                System.Func<int, bool> valid = to =>
                {
                    if (to == 4) return false;
                    for (int i = 0; i < Table.Length; i += 2) if (Table[i] == logical && Table[i + 1] == to) return true;
                    return false;
                };
                System.Action<string> mhook = kind =>
                {
                    mlog.Add(kind + ":" + (CharState)cur);
                    int d = m < dec.Length ? dec[m] : -1; m++;
                    if (d < 0) return;
                    bool ok = valid(d);
                    if (ok) { logical = d; q.Enqueue(d); }
                    mlog.Add((ok ? "+" : "-") + (CharState)d);
                };
                System.Action drain = () => { while (q.Count > 0) { int to = q.Dequeue(); mhook("Exit"); cur = to; mhook("Enter"); } };

                r.F.Start(CharState.Idle);
                mhook("Enter"); drain();
                for (int i = 0; i < ops.Length; i++)
                {
                    string opName;
                    if (ops[i] < 0) { opName = "Update"; r.F.Update(0.02f); mhook("Update"); drain(); }
                    else
                    {
                        opName = "Request(" + (CharState)ops[i] + ")";
                        bool got = r.F.RequestTransition((CharState)ops[i]);
                        bool exp = valid(ops[i]);
                        if (exp) { logical = ops[i]; q.Enqueue(ops[i]); drain(); }
                        if (got != exp) return "라운드 " + round + ", " + (CharState)cur + " 에서 " + opName + " 반환값 기대 " + exp + ", 결과 " + got;
                    }
                    string a = string.Join(" ", r.Log), b = string.Join(" ", mlog);
                    if (a != b || r.F.Current != (CharState)cur)
                    {
                        int from = System.Math.Max(0, mlog.Count - 8);
                        return "라운드 " + round + ", " + (i + 1) + "번째 연산 " + opName + " 뒤 훅 기록이 다름. 기대(끝부분) [" +
                            string.Join(" ", mlog.GetRange(from, mlog.Count - from)) + "], 결과(끝부분) [" +
                            string.Join(" ", r.Log.GetRange(System.Math.Max(0, r.Log.Count - 8), System.Math.Min(8, r.Log.Count))) + "], Current 기대 " + (CharState)cur + ", 결과 " + r.F.Current;
                    }
                }
            }
            return null;
        });
    }
}

