using System;
using System.Collections.Generic;

// ----- 아래 세 타입은 완성되어 있습니다. 수정하지 마세요. -----

// 결정적 시뮬레이션 상태: 정수만 쓰고, 난수도 상태 안의 시드에서만 나온다.
public sealed class GameState
{
    public int Frame;
    public int X, Y;
    public int Stamina = 100;
    public int Cooldown;
    public int EnemyHp = 1000;
    public uint RngState;

    public GameState(uint seed) { RngState = seed; }

    public int NextRandom(int maxExclusive)
    {
        RngState = RngState * 1664525u + 1013904223u;
        return (int)((RngState >> 16) % (uint)maxExclusive);
    }

    // 한 프레임 진행: 쿨다운 감소, 스태미나 회복
    public void Tick()
    {
        Frame++;
        if (Cooldown > 0) Cooldown--;
        if (Stamina < 100) Stamina++;
    }

    public string Snapshot()
    {
        return "F" + Frame + " P(" + X + "," + Y + ") ST" + Stamina + " CD" + Cooldown + " HP" + EnemyHp + " R" + RngState;
    }
}

public interface ICommand
{
    string Id { get; }                 // 기록과 리플레이에 쓰이는 고유 id (예: "attack")
    void Execute(GameState state);
}

public readonly struct RecordedCommand
{
    public readonly int Frame;         // 실행된 프레임 (실행 시점의 state.Frame)
    public readonly string CommandId;
    public RecordedCommand(int frame, string commandId) { Frame = frame; CommandId = commandId; }
}

public sealed class CommandInput
{
    private readonly Dictionary<string, ICommand> _commands = new Dictionary<string, ICommand>();
    private readonly Dictionary<string, string> _bindings = new Dictionary<string, string>();   // key -> commandId
    private readonly List<ICommand> _buffer = new List<ICommand>();                             // 이번 프레임에 실행할 커맨드
    private readonly List<RecordedCommand> _recording = new List<RecordedCommand>();

    public IReadOnlyList<RecordedCommand> Recording
    {
        get { return _recording; }
    }

    public void Register(ICommand command)
    {
        if (command == null) throw new ArgumentNullException(nameof(command));
        if (_commands.ContainsKey(command.Id)) throw new ArgumentException("이미 등록된 커맨드 id: " + command.Id);
        _commands.Add(command.Id, command);
    }

    public bool Bind(string key, string commandId)
    {
        if (commandId == null || !_commands.ContainsKey(commandId)) return false;
        _bindings[key] = commandId;         // 있으면 교체, 없으면 추가
        return true;
    }

    public bool Unbind(string key)
    {
        return _bindings.Remove(key);
    }

    public string GetBinding(string key)
    {
        string id;
        return _bindings.TryGetValue(key, out id) ? id : null;
    }

    public bool Press(string key)
    {
        string id;
        if (!_bindings.TryGetValue(key, out id)) return false;
        _buffer.Add(_commands[id]);         // 키는 여기서 끝난다. 이후로는 커맨드만 흐른다.
        return true;
    }

    public void AdvanceFrame(GameState state)
    {
        for (int i = 0; i < _buffer.Count; i++)
        {
            ICommand cmd = _buffer[i];
            _recording.Add(new RecordedCommand(state.Frame, cmd.Id));
            cmd.Execute(state);
        }
        _buffer.Clear();
        state.Tick();
    }

    public void Replay(GameState fresh, IReadOnlyList<RecordedCommand> stream, int totalFrames)
    {
        // 1) 먼저 전부 검증한다: 중간까지 재생하다가 멈춘 상태를 남기지 않는다.
        for (int i = 0; i < stream.Count; i++)
        {
            if (stream[i].CommandId == null || !_commands.ContainsKey(stream[i].CommandId))
                throw new InvalidOperationException("등록되지 않은 커맨드 id: " + stream[i].CommandId);
        }

        // 2) 라이브와 같은 순서: 그 프레임의 커맨드 실행 -> Tick. 스트림은 한 번만 훑는다.
        int next = 0;
        while (next < stream.Count && stream[next].Frame < fresh.Frame) next++;
        while (fresh.Frame < totalFrames)
        {
            while (next < stream.Count && stream[next].Frame == fresh.Frame)
            {
                _commands[stream[next].CommandId].Execute(fresh);
                next++;
            }
            fresh.Tick();
        }
    }
}

