using System;
using System.Collections.Generic;

public sealed class Bullet
{
    public int Damage;
    public int FramesLeft;
    public bool Piercing;                                   // 관통탄: 맞혀도 사라지지 않는다
    public readonly List<int> HitIds = new List<int>();     // 이미 맞힌 적 id (같은 적 중복 타격 방지)

    public void Reset()
    {
        Damage = 0;
        FramesLeft = 0;
    }
}

public sealed class ObjectPool<T> where T : class
{
    private readonly Stack<T> _free = new Stack<T>();
    private readonly Func<T> _create;
    private readonly Action<T> _onRelease;
    private readonly int _maxTotal;
    private int _created;

    // initialSize 개를 미리 만들어 두고, 전체 객체 수는 maxTotal 을 넘지 않는다.
    public ObjectPool(Func<T> create, Action<T> onRelease, int initialSize, int maxTotal)
    {
        if (create == null) throw new ArgumentNullException(nameof(create));
        if (initialSize < 0 || maxTotal < 1 || initialSize > maxTotal) throw new ArgumentOutOfRangeException(nameof(initialSize));
        _create = create;
        _onRelease = onRelease;
        _maxTotal = maxTotal;
        for (int i = 0; i < initialSize; i++) _free.Push(_create());
    }

    public int CountAll { get { return _created; } }                    // 이 풀이 만든 객체 수
    public int CountInactive { get { return _free.Count; } }            // 풀 안에서 대기 중
    public int CountActive { get { return _created - _free.Count; } }   // 빌려 나간 수

    // 대기 중인 객체가 있으면 그것을, 없으면 새로 만들어 돌려준다.
    // 전체 수가 maxTotal 에 도달했고 대기 중인 객체도 없으면 null.
    public T Get()
    {
        if (_free.Count > 0) return _free.Pop();
        if (_created >= _maxTotal) return null;
        _created++;
        return _create();
    }

    // 객체를 풀에 돌려놓는다. 돌려놓았으면 true.
    public bool Release(T item)
    {
        if (item == null) throw new ArgumentNullException(nameof(item));
        if (_onRelease != null) _onRelease(item);
        _free.Push(item);
        return true;
    }
}

public sealed class BulletSpawner
{
    private readonly ObjectPool<Bullet> _pool;
    private readonly List<Bullet> _live = new List<Bullet>();

    public BulletSpawner(int initialSize, int maxBullets)
    {
        _pool = new ObjectPool<Bullet>(() => new Bullet(), b => b.Reset(), initialSize, maxBullets);
    }

    public ObjectPool<Bullet> Pool { get { return _pool; } }
    public IReadOnlyList<Bullet> Live { get { return _live; } }

    // 탄환을 발사한다. 풀이 바닥났으면 null (이번 발사는 생략).
    public Bullet Fire(int damage, int frames, bool piercing)
    {
        Bullet b = _pool.Get();
        if (b == null) return null;
        b.Damage = damage;
        b.FramesLeft = frames;
        if (piercing) b.Piercing = true;
        _live.Add(b);
        return b;
    }

    // 탄환 b 가 적 enemyId 에 닿았다. 입힌 데미지를 반환한다(이미 맞힌 적이면 0).
    // 관통탄이 아니면 맞힌 즉시 사라진다.
    public int Hit(Bullet b, int enemyId)
    {
        if (b.HitIds.Contains(enemyId)) return 0;
        b.HitIds.Add(enemyId);
        int damage = b.Damage;
        if (!b.Piercing) Despawn(b);
        return damage;
    }

    // 한 프레임 진행: 수명이 다한 탄환을 회수한다.
    public void Tick()
    {
        for (int i = _live.Count - 1; i >= 0; i--)
        {
            Bullet b = _live[i];
            b.FramesLeft--;
            if (b.FramesLeft <= 0) Despawn(b);
        }
    }

    // 탄환을 회수한다. 실제로 회수했으면 true.
    public bool Despawn(Bullet b)
    {
        _live.Remove(b);
        return _pool.Release(b);
    }
}

problems.solutionCode:
using System;
using System.Collections.Generic;

public sealed class Bullet
{
    public int Damage;
    public int FramesLeft;
    public bool Piercing;                                   // 관통탄: 맞혀도 사라지지 않는다
    public readonly List<int> HitIds = new List<int>();     // 이미 맞힌 적 id (같은 적 중복 타격 방지)

    // 풀로 돌아갈 때 호출된다. 필드를 추가하면 여기에도 반드시 추가한다.
    public void Reset()
    {
        Damage = 0;
        FramesLeft = 0;
        Piercing = false;
        HitIds.Clear();
    }
}

public sealed class ObjectPool<T> where T : class
{
    private readonly Stack<T> _free = new Stack<T>();
    // 지금 빌려 나가 있는 객체들. Equals 재정의와 무관하게 '같은 인스턴스인가'로만 비교한다.
    private readonly HashSet<T> _active = new HashSet<T>(ReferenceEqualityComparer.Instance);
    private readonly Func<T> _create;
    private readonly Action<T> _onRelease;
    private readonly int _maxTotal;
    private int _created;

    // initialSize 개를 미리 만들어 두고, 전체 객체 수는 maxTotal 을 넘지 않는다.
    public ObjectPool(Func<T> create, Action<T> onRelease, int initialSize, int maxTotal)
    {
        if (create == null) throw new ArgumentNullException(nameof(create));
        if (initialSize < 0 || maxTotal < 1 || initialSize > maxTotal) throw new ArgumentOutOfRangeException(nameof(initialSize));
        _create = create;
        _onRelease = onRelease;
        _maxTotal = maxTotal;
        for (int i = 0; i < initialSize; i++)
        {
            _free.Push(_create());
            _created++;                 // 미리 만든 객체도 '만든 객체'다
        }
    }

    public int CountAll { get { return _created; } }                    // 이 풀이 만든 객체 수
    public int CountInactive { get { return _free.Count; } }            // 풀 안에서 대기 중
    public int CountActive { get { return _active.Count; } }            // 빌려 나간 수

    // 대기 중인 객체가 있으면 그것을, 없으면 새로 만들어 돌려준다.
    // 전체 수가 maxTotal 에 도달했고 대기 중인 객체도 없으면 null.
    public T Get()
    {
        T item;
        if (_free.Count > 0)
        {
            item = _free.Pop();
        }
        else
        {
            if (_created >= _maxTotal) return null;
            item = _create();
            _created++;
        }
        _active.Add(item);
        return item;
    }

    // item 이 지금 이 풀에서 빌려 나가 있는 객체인가.
    public bool IsActive(T item)
    {
        return item != null && _active.Contains(item);
    }

    // 객체를 풀에 돌려놓는다. 돌려놓았으면 true.
    // 이미 반납된 객체나 이 풀이 내준 적 없는 객체면 아무것도 하지 않고 false.
    public bool Release(T item)
    {
        if (item == null) throw new ArgumentNullException(nameof(item));
        if (!_active.Remove(item)) return false;
        if (_onRelease != null) _onRelease(item);
        _free.Push(item);
        return true;
    }
}

public sealed class BulletSpawner
{
    private readonly ObjectPool<Bullet> _pool;
    private readonly List<Bullet> _live = new List<Bullet>();

    public BulletSpawner(int initialSize, int maxBullets)
    {
        _pool = new ObjectPool<Bullet>(() => new Bullet(), b => b.Reset(), initialSize, maxBullets);
    }

    public ObjectPool<Bullet> Pool { get { return _pool; } }
    public IReadOnlyList<Bullet> Live { get { return _live; } }

    // 탄환을 발사한다. 풀이 바닥났으면 null (이번 발사는 생략).
    public Bullet Fire(int damage, int frames, bool piercing)
    {
        Bullet b = _pool.Get();
        if (b == null) return null;
        b.Damage = damage;
        b.FramesLeft = frames;
        b.Piercing = piercing;
        _live.Add(b);
        return b;
    }

    // 탄환 b 가 적 enemyId 에 닿았다. 입힌 데미지를 반환한다(이미 맞힌 적이면 0).
    // 관통탄이 아니면 맞힌 즉시 사라진다.
    public int Hit(Bullet b, int enemyId)
    {
        if (!_pool.IsActive(b)) return 0;           // 이미 회수된 탄환을 가리키는 낡은 참조
        if (b.HitIds.Contains(enemyId)) return 0;
        b.HitIds.Add(enemyId);
        int damage = b.Damage;
        if (!b.Piercing) Despawn(b);
        return damage;
    }

    // 한 프레임 진행: 수명이 다한 탄환을 회수한다.
    public void Tick()
    {
        for (int i = _live.Count - 1; i >= 0; i--)
        {
            Bullet b = _live[i];
            b.FramesLeft--;
            if (b.FramesLeft <= 0) Despawn(b);
        }
    }

    // 탄환을 회수한다. 실제로 회수했으면 true.
    public bool Despawn(Bullet b)
    {
        if (!_pool.Release(b)) return false;        // 중복 회수: 풀이 거절했으면 여기서 끝
        _live.Remove(b);
        return true;
    }
}

