public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    sealed class Item { public int Serial; public int Resets; }

    // Equals 를 재정의해 모든 인스턴스가 서로 "같다"고 답하는 타입
    sealed class Twin
    {
        public override bool Equals(object obj) { return obj is Twin; }
        public override int GetHashCode() { return 1; }
    }

    static string Counts(ObjectPool<Item> p)
    {
        return "All=" + p.CountAll + " Active=" + p.CountActive + " Inactive=" + p.CountInactive;
    }

    public static void Main()
    {
        Run("basic-reuse", () =>
        {
            int made = 0;
            var p = new ObjectPool<Item>(() => new Item { Serial = made++ }, it => it.Resets++, 0, 4);
            Item a = p.Get(), b = p.Get();
            if (a == null || b == null || ReferenceEquals(a, b)) return "Get 두 번이 서로 다른 객체를 주지 않음";
            if (Counts(p) != "All=2 Active=2 Inactive=0") return "Get 두 번 뒤 기대 All=2 Active=2 Inactive=0, 결과 " + Counts(p);
            if (!p.Release(a)) return "빌려 간 객체의 Release 가 false";
            if (a.Resets != 1) return "Release 때 onRelease 콜백이 정확히 한 번 호출되어야 함 (호출 " + a.Resets + "회)";
            if (Counts(p) != "All=2 Active=1 Inactive=1") return "Release 뒤 기대 All=2 Active=1 Inactive=1, 결과 " + Counts(p);
            Item c = p.Get();
            if (!ReferenceEquals(c, a) || made != 2) return "대기 중인 객체가 있는데 재사용하지 않고 새로 만듦 (생성 " + made + "회)";
            return null;
        });

        Run("double-release", () =>
        {
            int made = 0;
            var p = new ObjectPool<Item>(() => new Item { Serial = made++ }, it => it.Resets++, 0, 8);
            Item a = p.Get();
            if (!p.Release(a)) return "첫 Release 가 false";
            if (p.Release(a)) return "같은 객체의 두 번째 Release 가 true 를 반환";
            if (a.Resets != 1) return "거절된 Release 에서도 onRelease 가 호출됨 (총 " + a.Resets + "회)";
            if (Counts(p) != "All=1 Active=0 Inactive=1") return "중복 반납 뒤 기대 All=1 Active=0 Inactive=1, 결과 " + Counts(p);
            Item x = p.Get(), y = p.Get();
            if (ReferenceEquals(x, y)) return "Release(a) 두 번 뒤 Get 두 번이 같은 인스턴스를 반환 (두 사용자가 한 객체를 공유)";
            return null;
        });

        Run("foreign-release", () =>
        {
            var p = new ObjectPool<Item>(() => new Item(), it => it.Resets++, 1, 4);
            var stranger = new Item();
            if (p.Release(stranger)) return "이 풀이 내준 적 없는 객체의 Release 가 true 를 반환";
            if (stranger.Resets != 0 || Counts(p) != "All=1 Active=0 Inactive=1") return "외부 객체 Release 가 풀 상태를 바꿈: " + Counts(p);
            Item a = p.Get();
            if (ReferenceEquals(a, stranger)) return "풀이 외부 객체를 내줌";
            try { p.Release(null); return "Release(null) 이 ArgumentNullException 을 던지지 않음"; }
            catch (System.ArgumentNullException) { }
            return null;
        });

        Run("capacity-with-prewarm", () =>
        {
            int made = 0;
            var p = new ObjectPool<Item>(() => new Item { Serial = made++ }, null, 2, 3);
            if (Counts(p) != "All=2 Active=0 Inactive=2") return "initialSize 2 로 만든 직후 기대 All=2 Active=0 Inactive=2, 결과 " + Counts(p);
            var got = new System.Collections.Generic.List<Item>();
            for (int i = 0; i < 5; i++) got.Add(p.Get());
            int nonNull = 0;
            foreach (Item it in got) if (it != null) nonNull++;
            if (nonNull != 3 || made != 3) return "initialSize 2, maxTotal 3 에서 Get 5번: 객체 3개 뒤로는 null 이어야 함 (받은 객체 " + nonNull + "개, 생성 " + made + "회)";
            if (got[3] != null || got[4] != null) return "한도에 도달한 뒤의 Get 이 null 이 아님";
            if (Counts(p) != "All=3 Active=3 Inactive=0") return "기대 All=3 Active=3 Inactive=0, 결과 " + Counts(p);
            p.Release(got[1]);
            if (!ReferenceEquals(p.Get(), got[1])) return "반납된 객체가 있는데 Get 이 그것을 주지 않음";
            return null;
        });

        Run("reset-on-reuse", () =>
        {
            var sp = new BulletSpawner(0, 1);
            Bullet b = sp.Fire(10, 5, true);
            if (sp.Hit(b, 3) != 10 || sp.Hit(b, 3) != 0 || sp.Hit(b, 4) != 10) return "관통탄 명중 처리가 틀림 (적 3: 10, 다시 적 3: 0, 적 4: 10)";
            if (sp.Live.Count != 1) return "관통탄이 명중 후 사라짐";
            sp.Despawn(b);
            Bullet c = sp.Fire(7, 9, false);
            if (c == null) return "회수 후 Fire 가 null";
            if (c.Piercing) return "재사용된 탄환이 이전 탄환의 Piercing = true 를 그대로 가지고 있음";
            if (c.HitIds.Count != 0) return "재사용된 탄환의 HitIds 에 이전 기록이 남음: [" + string.Join(",", c.HitIds) + "]";
            if (c.Damage != 7 || c.FramesLeft != 9) return "Fire(7, 9) 인데 Damage=" + c.Damage + ", FramesLeft=" + c.FramesLeft;
            int dmg = sp.Hit(c, 3);
            if (dmg != 7) return "새 일반탄이 적 3 을 맞혔는데 데미지 " + dmg + " (이전 탄환의 명중 기록 때문에 무효 처리됨)";
            if (sp.Live.Count != 0 || sp.Pool.CountInactive != 1) return "일반탄이 명중 후 회수되지 않음";
            return null;
        });

        Run("spawner-double-despawn", () =>
        {
            var sp = new BulletSpawner(0, 8);
            Bullet a = sp.Fire(5, 10, false);
            if (!sp.Despawn(a)) return "첫 Despawn 이 false";
            if (sp.Despawn(a)) return "같은 탄환의 두 번째 Despawn 이 true 를 반환";
            Bullet b = sp.Fire(1, 10, false), c = sp.Fire(2, 10, false);
            if (ReferenceEquals(b, c)) return "Despawn 을 두 번 호출한 뒤 Fire 두 번이 같은 Bullet 을 반환";
            if (b.Damage != 1 || c.Damage != 2) return "두 탄환의 데미지가 섞임: " + b.Damage + ", " + c.Damage;
            if (sp.Live.Count != 2 || sp.Pool.CountActive != 2 || sp.Pool.CountAll != 2) return "기대 Live=2 Active=2 All=2, 결과 Live=" + sp.Live.Count + " Active=" + sp.Pool.CountActive + " All=" + sp.Pool.CountAll;
            return null;
        });

        Run("tick-expiry", () =>
        {
            var sp = new BulletSpawner(2, 3);
            Bullet a = sp.Fire(1, 1, false), b = sp.Fire(2, 3, true), c = sp.Fire(3, 2, false);
            if (a == null || b == null || c == null) return "한도 3 안에서 Fire 가 null";
            if (sp.Fire(4, 5, false) != null) return "initialSize 2, maxBullets 3 인데 네 번째 탄환이 발사됨";
            sp.Tick();
            if (sp.Live.Count != 2) return "1프레임 뒤 살아 있는 탄환 기대 2, 결과 " + sp.Live.Count;
            sp.Tick(); sp.Tick();
            if (sp.Live.Count != 0 || sp.Pool.CountInactive != 3 || sp.Pool.CountActive != 0) return "모두 만료된 뒤 기대 Live=0 Inactive=3 Active=0, 결과 Live=" + sp.Live.Count + " Inactive=" + sp.Pool.CountInactive + " Active=" + sp.Pool.CountActive;
            Bullet d = sp.Fire(9, 4, false);
            return d != null && !d.Piercing && d.HitIds.Count == 0 && d.Damage == 9 ? null : "만료 후 재사용된 탄환의 상태가 깨끗하지 않음";
        });

        Run("reference-identity", () =>
        {
            var p = new ObjectPool<Twin>(() => new Twin(), null, 0, 4);
            Twin a = p.Get(), b = p.Get();
            if (a == null || b == null || ReferenceEquals(a, b)) return "Get 두 번이 서로 다른 인스턴스를 주지 않음";
            if (p.CountActive != 2) return "Equals 가 같다고 답하는 서로 다른 인스턴스 2개를 빌렸는데 CountActive = " + p.CountActive;
            if (!p.Release(a)) return "빌려 간 a 의 Release 가 false";
            if (p.Release(a)) return "이미 반납한 a 를 다시 Release 했는데 true (Equals 가 같은 b 와 혼동하고 있지 않은가?)";
            if (p.CountActive != 1 || p.CountInactive != 1) return "기대 Active=1 Inactive=1, 결과 Active=" + p.CountActive + " Inactive=" + p.CountInactive;
            if (p.Release(new Twin())) return "풀이 내준 적 없는 인스턴스(Equals 로는 b 와 같음)의 Release 가 true";
            if (!p.Release(b)) return "아직 빌려 나가 있는 b 의 Release 가 false";
            return p.CountActive == 0 && p.CountInactive == 2 && p.CountAll == 2 ? null
                : "기대 All=2 Active=0 Inactive=2, 결과 All=" + p.CountAll + " Active=" + p.CountActive + " Inactive=" + p.CountInactive;
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(8086);
            for (int round = 0; round < 200; round++)
            {
                int max = rng.Next(1, 7), init = rng.Next(0, max + 1), made = 0;
                var p = new ObjectPool<Item>(() => new Item { Serial = made++ }, it => it.Resets++, init, max);
                var held = new System.Collections.Generic.List<Item>();
                var returned = new System.Collections.Generic.List<Item>();
                for (int step = 0; step < 60; step++)
                {
                    int op = rng.Next(100);
                    if (op < 50)
                    {
                        Item it = p.Get();
                        bool expectNull = held.Count == max;
                        if ((it == null) != expectNull) return "라운드 " + round + " (init " + init + ", max " + max + "): 빌려 나간 수 " + held.Count + " 에서 Get 이 " + (it == null ? "null" : "객체") + " 를 반환";
                        if (it == null) continue;
                        if (held.Contains(it)) return "라운드 " + round + ": 아직 사용 중인 객체(#" + it.Serial + ")를 다시 내줌";
                        held.Add(it); returned.Remove(it);
                    }
                    else if (op < 80 && held.Count > 0)
                    {
                        Item it = held[rng.Next(held.Count)];
                        if (!p.Release(it)) return "라운드 " + round + ": 사용 중인 객체의 Release 가 false";
                        held.Remove(it); returned.Add(it);
                    }
                    else if (returned.Count > 0)
                    {
                        Item it = returned[rng.Next(returned.Count)];
                        if (p.Release(it)) return "라운드 " + round + ": 이미 반납된 객체(#" + it.Serial + ")의 Release 가 true";
                    }
                    if (made > max || p.CountAll != made) return "라운드 " + round + ": 생성 " + made + "회, CountAll " + p.CountAll + " (maxTotal " + max + ")";
                    if (p.CountActive != held.Count || p.CountInactive != made - held.Count)
                        return "라운드 " + round + ": 기대 Active=" + held.Count + " Inactive=" + (made - held.Count) + ", 결과 " + Counts(p);
                }
            }
            return null;
        });
    }
}

