using System;

// 아케이드 슈터의 점수 클래스. 한 클래스가 세 가지 이유로 수정된다:
//   - 기획자가 콤보 규칙을 바꿀 때
//   - UI 디자이너가 HUD 표기를 바꿀 때
//   - 세이브 포맷이 바뀔 때
// 실습: 동작을 그대로 둔 채, 바뀌는 이유마다 클래스를 하나씩 갖도록 나누세요.
public sealed class ScoreManager
{
    public int Score { get; private set; }
    public int Combo { get; private set; }

    // 규칙: 적을 잡을 때마다 콤보가 1 오르고, 점수는 기본 점수 x 콤보만큼 오른다. 콤보는 최대 5.
    public void AddKill(int basePoints)
    {
        if (Combo < 5) Combo++;
        Score += basePoints * Combo;
    }

    // 규칙: 피격되면 콤보가 끊긴다.
    public void OnPlayerHit()
    {
        Combo = 0;
    }

    // 표시: "SCORE 001250  x3" (콤보가 0 이면 배수를 표시하지 않는다)
    public string BuildHudText()
    {
        string text = "SCORE " + Score.ToString("D6");
        if (Combo > 0) text += "  x" + Combo;
        return text;
    }

    // 저장: "점수;콤보"
    public string Serialize()
    {
        return Score + ";" + Combo;
    }

    public void Deserialize(string data)
    {
        string[] parts = data.Split(';');
        Score = int.Parse(parts[0]);
        Combo = int.Parse(parts[1]);
    }
}

problems.solutionCode:
using System;

// 바뀌는 이유 1: 게임 규칙 (기획자). 점수와 콤보의 상태와, 그것을 바꾸는 규칙만 안다.
public sealed class ScoreTracker
{
    public const int MaxCombo = 5;

    public int Score { get; private set; }
    public int Combo { get; private set; }

    public ScoreTracker() { }

    // 저장된 값으로 복원할 때 쓰는 생성자. setter 를 public 으로 열지 않기 위해 둔다.
    // 원본 Deserialize 가 값을 검증하지 않았으므로 여기서도 하지 않는다(리팩터링은 동작을 바꾸지 않는다).
    public ScoreTracker(int score, int combo)
    {
        Score = score;
        Combo = combo;
    }

    public void AddKill(int basePoints)
    {
        if (Combo < MaxCombo) Combo++;
        Score += basePoints * Combo;
    }

    public void OnPlayerHit()
    {
        Combo = 0;
    }
}

// 바뀌는 이유 2: 화면 표기 (UI 디자이너). 값을 읽어 문자열을 만들 뿐 상태를 바꾸지 않는다.
public static class ScoreHudFormatter
{
    public static string Format(ScoreTracker tracker)
    {
        string text = "SCORE " + tracker.Score.ToString("D6");
        if (tracker.Combo > 0) text += "  x" + tracker.Combo;
        return text;
    }
}

// 바뀌는 이유 3: 세이브 포맷 (저장 시스템 담당). 문자열과 ScoreTracker 사이의 변환만 안다.
public static class ScoreSaveCodec
{
    public static string Serialize(ScoreTracker tracker)
    {
        return tracker.Score + ";" + tracker.Combo;
    }

    public static ScoreTracker Deserialize(string data)
    {
        string[] parts = data.Split(';');
        return new ScoreTracker(int.Parse(parts[0]), int.Parse(parts[1]));
    }
}

