using System;
using System.Collections.Generic;

// ----- 아래 Component 는 완성되어 있습니다. 수정하지 마세요. -----

public abstract class Component
{
    // 붙어 있는 엔티티. 어디에도 붙어 있지 않으면 null. Entity 만 값을 바꾼다.
    public Entity Owner { get; internal set; }

    // 업데이트 순서 키. 작은 값이 먼저 업데이트된다. 붙어 있는 동안에는 값이 바뀌지 않는다.
    public virtual int Order { get { return 0; } }

    public virtual void OnAttach() { }
    public virtual void OnDetach() { }
    public virtual void Update(float dt) { }
}

public sealed class Entity
{
    // 타입 -> 컴포넌트: Get / Has / Remove 의 O(1) 조회용.
    private readonly Dictionary<Type, Component> _byType = new Dictionary<Type, Component>();

    // 항상 (Order 오름차순, 같으면 붙인 순서)로 정렬된 상태를 유지한다. 자리는 Add 때 한 번만 찾는다.
    private readonly List<Component> _ordered = new List<Component>();

    // Update 한 번이 순회할 스냅숏. 매번 새로 만들지 않고 재사용한다.
    private readonly List<Component> _pass = new List<Component>();

    public int Count
    {
        get { return _ordered.Count; }
    }

    public T Add<T>(T component) where T : Component
    {
        if (component == null) throw new ArgumentNullException(nameof(component));
        if (component.Owner != null) throw new InvalidOperationException("이미 엔티티에 붙어 있는 컴포넌트");
        Type type = component.GetType();
        if (_byType.ContainsKey(type)) throw new InvalidOperationException("같은 타입의 컴포넌트가 이미 있음: " + type.Name);

        // 뒤에서부터 자리를 찾는다. 자기보다 Order 가 큰 것만 건너뛰므로 같은 Order 끼리는 붙인 순서가 유지된다.
        int order = component.Order;
        int index = _ordered.Count;
        while (index > 0 && _ordered[index - 1].Order > order) index--;

        _ordered.Insert(index, component);
        _byType.Add(type, component);
        component.Owner = this;
        component.OnAttach();
        return component;
    }

    public T Get<T>() where T : Component
    {
        Component found;
        return _byType.TryGetValue(typeof(T), out found) ? (T)found : null;
    }

    public bool Has<T>() where T : Component
    {
        return _byType.ContainsKey(typeof(T));
    }

    public bool Remove<T>() where T : Component
    {
        Component found;
        if (!_byType.TryGetValue(typeof(T), out found)) return false;
        _byType.Remove(typeof(T));
        _ordered.Remove(found);
        found.OnDetach();       // 아직 Owner 가 살아 있어 형제 컴포넌트에 접근해 정리할 수 있다
        found.Owner = null;
        return true;
    }

    public void GetAll<T>(List<T> results) where T : class
    {
        if (results == null) throw new ArgumentNullException(nameof(results));
        results.Clear();
        for (int i = 0; i < _ordered.Count; i++)
        {
            T match = _ordered[i] as T;
            if (match != null) results.Add(match);
        }
    }

    public void Update(float dt)
    {
        // 순회 대상을 고정한다. 순회 중에 붙은 컴포넌트는 스냅숏에 없으므로 다음 Update 부터 돈다.
        _pass.Clear();
        _pass.AddRange(_ordered);
        for (int i = 0; i < _pass.Count; i++)
        {
            Component c = _pass[i];
            // 이번 순회 중에 떼어진 컴포넌트는 Owner 가 더 이상 이 엔티티가 아니다.
            if (c.Owner == this) c.Update(dt);
        }
        _pass.Clear();      // 떼어 낸 컴포넌트를 붙잡고 있지 않도록 비운다
    }
}

