public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    interface IMarked { }

    static readonly System.Collections.Generic.List<string> Log = new System.Collections.Generic.List<string>();

    abstract class Probe : Component
    {
        readonly int _order;
        public readonly string Tag;
        public float LastDt;
        public string AttachSeen = "", DetachSeen = "";
        public System.Action<Probe> OnUpdate;
        protected Probe(string tag, int order) { Tag = tag; _order = order; }
        public override int Order { get { return _order; } }
        public override void Update(float dt) { LastDt = dt; Log.Add(Tag); if (OnUpdate != null) OnUpdate(this); }
        protected abstract bool OwnerHasMe();
        string Observe() { return Owner == null ? "owner=null;" : "owner=set," + (OwnerHasMe() ? "registered;" : "unregistered;"); }
        public override void OnAttach() { AttachSeen += Observe(); }
        public override void OnDetach() { DetachSeen += Observe(); }
    }
    sealed class C0 : Probe, IMarked { public C0(int o = 0) : base("C0", o) { } protected override bool OwnerHasMe() { return Owner.Get<C0>() == this; } }
    sealed class C1 : Probe { public C1(int o = 0) : base("C1", o) { } protected override bool OwnerHasMe() { return Owner.Get<C1>() == this; } }
    sealed class C2 : Probe, IMarked { public C2(int o = 0) : base("C2", o) { } protected override bool OwnerHasMe() { return Owner.Get<C2>() == this; } }
    sealed class C3 : Probe { public C3(int o = 0) : base("C3", o) { } protected override bool OwnerHasMe() { return Owner.Get<C3>() == this; } }
    sealed class C4 : Probe, IMarked { public C4(int o = 0) : base("C4", o) { } protected override bool OwnerHasMe() { return Owner.Get<C4>() == this; } }

    static string Pass(Entity e, float dt = 0.5f) { Log.Clear(); e.Update(dt); return string.Join(",", Log); }

    static string Thrown(System.Action a)
    {
        try { a(); } catch (System.Exception ex) { return ex.GetType().Name; }
        return "없음";
    }

    static string Tags(System.Collections.Generic.List<Probe> list)
    {
        var s = new System.Collections.Generic.List<string>();
        foreach (Probe p in list) s.Add(p.Tag);
        return string.Join(",", s);
    }

    public static void Main()
    {
        Run("add-get-has-count", () =>
        {
            var e = new Entity();
            if (e.Count != 0 || e.Has<C0>() || e.Get<C0>() != null) return "빈 엔티티는 Count 0, Has false, Get null 이어야 함";
            var a = new C0(); var b = new C1();
            if (e.Add(a) != a) return "Add 는 넘겨받은 컴포넌트를 그대로 반환해야 함";
            e.Add(b);
            if (e.Count != 2) return "두 개를 붙인 뒤 Count 기대 2, 결과 " + e.Count;
            if (e.Get<C0>() != a || e.Get<C1>() != b) return "Get<T> 가 붙인 인스턴스를 돌려주지 않음";
            if (!e.Has<C1>() || e.Has<C2>() || e.Get<C2>() != null) return "없는 타입에 대해 Has 는 false, Get 은 null 이어야 함";
            if (a.Owner != e || b.Owner != e) return "붙인 컴포넌트의 Owner 가 엔티티가 아님";
            if (e.Get<Probe>() != null || e.Has<Probe>()) return "Get<T> / Has<T> 는 실제 타입이 정확히 T 인 것만 찾아야 함 (기반 타입으로는 null / false)";
            return null;
        });

        Run("add-validation", () =>
        {
            var e = new Entity(); var other = new Entity();
            var a = new C0();
            e.Add(a);
            string t = Thrown(() => e.Add<C0>(null));
            if (t != "ArgumentNullException") return "Add(null) 기대 ArgumentNullException, 결과 " + t;
            t = Thrown(() => e.Add(new C0(5)));
            if (t != "InvalidOperationException") return "같은 타입을 두 번 Add: 기대 InvalidOperationException, 결과 " + t;
            if (e.Get<C0>() != a || e.Count != 1) return "실패한 Add 가 기존 컴포넌트를 바꿈";
            t = Thrown(() => other.Add(a));
            if (t != "InvalidOperationException") return "다른 엔티티에 붙어 있는 컴포넌트를 Add: 기대 InvalidOperationException, 결과 " + t;
            if (a.Owner != e || other.Count != 0 || other.Has<C0>()) return "실패한 Add 가 Owner 또는 다른 엔티티의 상태를 바꿈";
            Component asBase = new C1();
            e.Add<Component>(asBase);
            if (e.Get<C1>() != asBase) return "Add<Component>(new C1()) 은 실제 타입 C1 로 등록되어야 함 (키는 GetType())";
            t = Thrown(() => e.Add(new C1()));
            if (t != "InvalidOperationException") return "실제 타입 기준 중복 검사가 안 됨: 결과 " + t;
            return null;
        });

        Run("update-order", () =>
        {
            var e = new Entity();
            e.Add(new C0(10)); e.Add(new C1(-5)); e.Add(new C2(10)); e.Add(new C3(0)); e.Add(new C4(-5));
            string got = Pass(e, 0.25f);
            if (got != "C1,C4,C3,C0,C2") return "Order 10,-5,10,0,-5 순으로 붙임: 기대 C1,C4,C3,C0,C2, 결과 " + got;
            if (e.Get<C2>().LastDt != 0.25f) return "Update 에 dt 가 그대로 전달되지 않음";
            got = Pass(e);
            return got == "C1,C4,C3,C0,C2" ? null : "두 번째 Update 의 순서가 달라짐: " + got;
        });

        Run("get-all-by-interface", () =>
        {
            var e = new Entity();
            e.Add(new C0(3)); e.Add(new C1(1)); e.Add(new C2(2)); e.Add(new C4(3));
            var marked = new System.Collections.Generic.List<IMarked>();
            marked.Add(new C4());
            e.GetAll(marked);
            var names = new System.Collections.Generic.List<string>();
            foreach (IMarked m in marked) names.Add(((Probe)m).Tag);
            string got = string.Join(",", names);
            if (got != "C2,C0,C4") return "GetAll<IMarked>: results 를 비우고 업데이트 순서대로 담아야 함. 기대 C2,C0,C4, 결과 " + got;
            var all = new System.Collections.Generic.List<Probe>();
            e.GetAll(all);
            if (Tags(all) != "C1,C2,C0,C4") return "GetAll<Probe>(기반 클래스) 기대 C1,C2,C0,C4, 결과 " + Tags(all);
            string t = Thrown(() => e.GetAll<IMarked>(null));
            return t == "ArgumentNullException" ? null : "GetAll(null) 기대 ArgumentNullException, 결과 " + t;
        });

        Run("remove-lifecycle", () =>
        {
            var e = new Entity();
            var a = new C0(); var b = new C1();
            e.Add(a); e.Add(b);
            if (a.AttachSeen != "owner=set,registered;") return "OnAttach 는 한 번, Owner 가 설정되고 Get 으로 찾을 수 있는 상태에서 불려야 함 (관찰: " + a.AttachSeen + ")";
            if (e.Remove<C2>()) return "없는 타입의 Remove 는 false 여야 함";
            if (!e.Remove<C0>()) return "있는 타입의 Remove 가 false";
            if (a.DetachSeen != "owner=set,unregistered;") return "OnDetach 는 한 번, 등록이 해제되고 Owner 는 아직 엔티티인 상태에서 불려야 함 (관찰: " + a.DetachSeen + ")";
            if (a.Owner != null) return "Remove 뒤 Owner 가 null 이 아님";
            if (e.Has<C0>() || e.Count != 1 || e.Remove<C0>()) return "Remove 뒤 Has / Count / 두 번째 Remove 결과가 틀림";
            string got = Pass(e);
            if (got != "C1") return "뗀 컴포넌트가 계속 업데이트됨: " + got;
            var e2 = new Entity();
            e2.Add(a);
            if (a.Owner != e2 || Pass(e2) != "C0") return "뗀 컴포넌트를 다른 엔티티에 다시 붙일 수 있어야 함";
            return null;
        });

        Run("remove-during-update", () =>
        {
            var e = new Entity();
            var a = new C0(0); var b = new C1(1); var c = new C2(2); var d = new C3(3);
            e.Add(a); e.Add(b); e.Add(c); e.Add(d);
            string seen = "";
            a.OnUpdate = self =>
            {
                Entity owner = self.Owner;
                owner.Remove<C2>(); seen = owner.Has<C2>() + "/" + owner.Count;
                owner.Remove<C0>(); seen += "/" + owner.Has<C0>() + "/" + owner.Count;
            };
            string got = Pass(e);
            if (got != "C0,C1,C3") return "C0 가 Update 중에 C2 와 자기 자신을 뗌: 기대 C0,C1,C3 (C2 는 이번 순회에서 호출되지 않음), 결과 " + got;
            if (seen != "False/3/False/2") return "순회 중 Remove 는 Has / Count 에 즉시 보여야 함 (기대 False/3/False/2, 관찰 " + seen + ")";
            if (e.Count != 2 || c.Owner != null || a.Owner != null) return "순회 중 Remove 가 즉시 반영되지 않음";
            got = Pass(e);
            return got == "C1,C3" ? null : "다음 Update 기대 C1,C3, 결과 " + got;
        });

        Run("add-during-update", () =>
        {
            var e = new Entity();
            var a = new C0(0); var b = new C1(1);
            e.Add(a); e.Add(b);
            string seen = "";
            a.OnUpdate = self =>
            {
                if (self.Owner.Has<C2>()) return;
                self.Owner.Add(new C2(-100)); self.Owner.Add(new C3(100));
                seen = self.Owner.Has<C2>() + "/" + self.Owner.Count;
            };
            string got = Pass(e);
            if (got != "C0,C1") return "Update 중에 붙인 컴포넌트는 다음 Update 부터 돌아야 함: 기대 C0,C1, 결과 " + got;
            if (seen != "True/4") return "순회 중 Add 는 Has / Count 에 즉시 보여야 함 (관찰: " + seen + ")";
            var all = new System.Collections.Generic.List<Probe>();
            e.GetAll(all);
            if (Tags(all) != "C2,C0,C1,C3") return "GetAll 기대 C2,C0,C1,C3, 결과 " + Tags(all);
            got = Pass(e);
            return got == "C2,C0,C1,C3" ? null : "다음 Update 기대 C2,C0,C1,C3, 결과 " + got;
        });

        Run("random-vs-model", () =>
        {
            var rng = new System.Random(2024);
            for (int round = 0; round < 200; round++)
            {
                var e = new Entity();
                var model = new System.Collections.Generic.List<Probe>();   // 붙인 순서
                for (int step = 0; step < 40; step++)
                {
                    int kind = rng.Next(5), order = rng.Next(-2, 3), op = rng.Next(10);
                    string tag = "C" + kind;
                    Probe existing = model.Find(p => p.Tag == tag);
                    if (op < 5)
                    {
                        Probe p = kind == 0 ? new C0(order) : kind == 1 ? new C1(order) : kind == 2 ? new C2(order) : kind == 3 ? (Probe)new C3(order) : new C4(order);
                        string t = Thrown(() => e.Add(p));
                        if (existing == null) { if (t != "없음") return "라운드 " + round + ": 정상 Add 에서 " + t; model.Add(p); }
                        else if (t != "InvalidOperationException") return "라운드 " + round + ": 중복 Add 에서 기대 InvalidOperationException, 결과 " + t;
                    }
                    else if (op < 8)
                    {
                        bool got = kind == 0 ? e.Remove<C0>() : kind == 1 ? e.Remove<C1>() : kind == 2 ? e.Remove<C2>() : kind == 3 ? e.Remove<C3>() : e.Remove<C4>();
                        if (got != (existing != null)) return "라운드 " + round + ": Remove 반환값 기대 " + (existing != null) + ", 결과 " + got;
                        model.Remove(existing);
                    }
                    else
                    {
                        var sorted = new System.Collections.Generic.List<Probe>(model);
                        for (int i = 1; i < sorted.Count; i++)      // 안정적인 삽입 정렬
                            for (int j = i; j > 0 && sorted[j - 1].Order > sorted[j].Order; j--) { Probe tmp = sorted[j]; sorted[j] = sorted[j - 1]; sorted[j - 1] = tmp; }
                        string exp = string.Join(",", sorted.ConvertAll(p => p.Tag + "(" + p.Order + ")"));
                        Log.Clear(); e.Update(1f);
                        var all = new System.Collections.Generic.List<Probe>(); e.GetAll(all);
                        string gotAll = string.Join(",", all.ConvertAll(p => p.Tag + "(" + p.Order + ")"));
                        string expLog = string.Join(",", sorted.ConvertAll(p => p.Tag));
                        if (string.Join(",", Log) != expLog || gotAll != exp || e.Count != model.Count)
                            return "라운드 " + round + ": 기대 순서 [" + exp + "], Update 호출 [" + string.Join(",", Log) + "], GetAll [" + gotAll + "], Count " + e.Count;
                    }
                }
            }
            return null;
        });
    }
}

