public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // Equals 를 재정의한 출처: 값이 같아도 다른 인스턴스는 다른 출처로 취급되어야 한다.
    sealed class Gear
    {
        public readonly string Name;
        public Gear(string name) { Name = name; }
        public override bool Equals(object obj) { return obj is Gear && ((Gear)obj).Name == Name; }
        public override int GetHashCode() { return Name.GetHashCode(); }
    }

    sealed class Ref { public int Id; public ModifierKind Kind; public int Value, Order; public object Source; }

    // 참조 계산: 추가 순서 목록을 (order, 추가 순서)로 안정 정렬해 하나씩 적용
    static long RefValue(int baseValue, System.Collections.Generic.List<Ref> mods)
    {
        var sorted = new System.Collections.Generic.List<Ref>(mods);
        for (int i = 1; i < sorted.Count; i++)
            for (int j = i; j > 0 && sorted[j - 1].Order > sorted[j].Order; j--) { Ref t = sorted[j]; sorted[j] = sorted[j - 1]; sorted[j - 1] = t; }
        long v = baseValue;
        foreach (Ref m in sorted) v = m.Kind == ModifierKind.Add ? v + m.Value : v * (100 + m.Value) / 100;
        return v;
    }

    public static void Main()
    {
        Run("pipeline-order", () =>
        {
            var s = new Stat(100);
            if (s.Value != 100 || s.ModifierCount != 0 || s.BaseValue != 100) return "수정자가 없으면 Value 는 BaseValue 여야 함 (결과 " + s.Value + ")";
            s.AddModifier(ModifierKind.Add, 5, 20, null);
            s.AddModifier(ModifierKind.Multiply, 50, 10, null);
            s.AddModifier(ModifierKind.Add, 20, 0, null);
            if (s.Value != 185) return "기본 100, [+5 order 20], [x1.5 order 10], [+20 order 0]: (100+20)*1.5+5 = 185 기대, 결과 " + s.Value;
            if (s.ModifierCount != 3) return "ModifierCount 기대 3, 결과 " + s.ModifierCount;
            var d = new Stat(200);
            d.AddModifier(ModifierKind.Multiply, -30, 0, null);
            d.AddModifier(ModifierKind.Add, -40, 1, null);
            return d.Value == 100 ? null : "기본 200, [-30%], [-40]: 기대 100, 결과 " + d.Value;
        });

        Run("same-order-keeps-add-order", () =>
        {
            var a = new Stat(10);
            a.AddModifier(ModifierKind.Add, 5, 3, null);
            a.AddModifier(ModifierKind.Multiply, 100, 3, null);
            var b = new Stat(10);
            b.AddModifier(ModifierKind.Multiply, 100, 3, null);
            b.AddModifier(ModifierKind.Add, 5, 3, null);
            if (a.Value != 30 || b.Value != 25) return "order 가 같으면 추가 순서대로: (10+5)*2 = 30, 10*2+5 = 25 기대, 결과 " + a.Value + ", " + b.Value;
            var c = new Stat(1);
            for (int i = 0; i < 20; i++) c.AddModifier(i % 2 == 0 ? ModifierKind.Add : ModifierKind.Multiply, i % 2 == 0 ? 3 : 100, 7, null);
            long exp = 1; for (int i = 0; i < 20; i++) exp = i % 2 == 0 ? exp + 3 : exp * 2;
            return c.Value == exp ? null : "order 가 모두 7 인 수정자 20개(+3 과 x2 번갈아): 기대 " + exp + ", 결과 " + c.Value;
        });

        Run("truncation-each-step", () =>
        {
            var s = new Stat(7);
            s.AddModifier(ModifierKind.Multiply, 50, 0, null);
            s.AddModifier(ModifierKind.Add, 1, 1, null);
            s.AddModifier(ModifierKind.Multiply, 50, 2, null);
            if (s.Value != 16) return "기본 7, x1.5 -> +1 -> x1.5: 단계마다 버림 7 -> 10 -> 11 -> 16 기대, 결과 " + s.Value;
            var n = new Stat(-7);
            n.AddModifier(ModifierKind.Multiply, 50, 0, null);
            if (n.Value != -10) return "기본 -7, x1.5: -10.5 는 0 쪽으로 버려 -10 기대, 결과 " + n.Value;
            var exact = new Stat(100);
            exact.AddModifier(ModifierKind.Multiply, 15, 0, null);
            if (exact.Value != 115) return "기본 100, x1.15: 정수 계산으로 정확히 115 기대, 결과 " + exact.Value + " (부동소수점 계산?)";
            var big = new Stat(2000000000);
            big.AddModifier(ModifierKind.Multiply, 200, 0, null);
            big.AddModifier(ModifierKind.Multiply, 200, 0, null);
            return big.Value == 18000000000L ? null : "기본 20억, x3, x3: long 으로 180억 기대, 결과 " + big.Value;
        });

        Run("remove-by-id", () =>
        {
            var s = new Stat(50);
            int a = s.AddModifier(ModifierKind.Add, 10, 0, null);
            int b = s.AddModifier(ModifierKind.Multiply, 100, 1, null);
            int c = s.AddModifier(ModifierKind.Add, 1, 2, null);
            if (a <= 0 || b <= 0 || c <= 0 || a == b || b == c || a == c) return "id 는 서로 다른 양수여야 함 (" + a + ", " + b + ", " + c + ")";
            if (s.Value != 121) return "기대 121, 결과 " + s.Value;
            if (!s.RemoveModifier(b)) return "있는 id 의 RemoveModifier 가 false";
            if (s.Value != 61 || s.ModifierCount != 2) return "x2 제거 뒤 기대 61 / 2개, 결과 " + s.Value + " / " + s.ModifierCount;
            if (s.RemoveModifier(b)) return "이미 제거한 id 를 다시 제거하면 false 여야 함";
            if (s.RemoveModifier(-1) || s.RemoveModifier(0) || s.RemoveModifier(a + b + c + 1000)) return "없는 id 의 RemoveModifier 는 false 여야 함";
            if (s.Value != 61 || s.ModifierCount != 2) return "실패한 Remove 가 상태를 바꿈";
            int d = s.AddModifier(ModifierKind.Add, 100, 5, null);
            if (d == a || d == b || d == c) return "제거된 id " + b + " 를 포함해 이전 id 가 재사용됨: " + d;
            s.RemoveModifier(a); s.RemoveModifier(c); s.RemoveModifier(d);
            return s.Value == 50 && s.ModifierCount == 0 ? null : "전부 제거하면 BaseValue 로 돌아와야 함 (결과 " + s.Value + ")";
        });

        Run("remove-by-source", () =>
        {
            var s = new Stat(100);
            var sword = new Gear("sword"); var twin = new Gear("sword"); var ring = new Gear("ring");
            s.AddModifier(ModifierKind.Add, 10, 0, sword);
            s.AddModifier(ModifierKind.Multiply, 10, 5, sword);
            s.AddModifier(ModifierKind.Add, 7, 0, twin);
            s.AddModifier(ModifierKind.Add, 3, 9, ring);
            s.AddModifier(ModifierKind.Add, 1000, 9, null);
            if (s.Value != 1131) return "기대 (100+10+7)*1.1 = 128 -> +3 +1000 = 1131, 결과 " + s.Value;
            if (s.RemoveAllFromSource(null) != 0 || s.ModifierCount != 5) return "RemoveAllFromSource(null) 은 0 을 반환하고 아무것도 제거하지 않아야 함";
            int n = s.RemoveAllFromSource(sword);
            if (n != 2) return "sword 가 건 수정자 2개 제거 기대 (Equals 가 같은 다른 인스턴스 twin 의 것은 남김), 결과 " + n;
            if (s.Value != 1110 || s.ModifierCount != 3) return "sword 제거 뒤 기대 1110 / 3개, 결과 " + s.Value + " / " + s.ModifierCount;
            if (s.RemoveAllFromSource(sword) != 0 || s.RemoveAllFromSource(new Gear("ring")) != 0) return "해당 출처의 수정자가 없으면 0 이어야 함";
            return s.RemoveAllFromSource(twin) == 1 && s.RemoveAllFromSource(ring) == 1 && s.Value == 1100 ? null : "twin, ring 제거 뒤 기대 1100, 결과 " + s.Value;
        });

        Run("base-change-recalculates", () =>
        {
            var s = new Stat(10);
            s.AddModifier(ModifierKind.Multiply, 100, 0, null);
            long first = s.Value, again = s.Value;
            if (first != 20 || again != 20) return "연속으로 읽은 Value 가 다름: " + first + ", " + again;
            s.BaseValue = 30;
            if (s.BaseValue != 30 || s.Value != 60) return "BaseValue 를 30 으로 바꾼 뒤 기대 60, 결과 " + s.Value;
            int id = s.AddModifier(ModifierKind.Add, 5, -1, null);
            if (s.Value != 70) return "읽은 뒤에 추가한 수정자가 반영되지 않음: 기대 (30+5)*2 = 70, 결과 " + s.Value;
            s.RemoveModifier(id);
            s.BaseValue = 30;
            return s.Value == 60 ? null : "읽은 뒤에 제거한 수정자가 계속 반영됨: 기대 60, 결과 " + s.Value;
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(4242);
            for (int round = 0; round < 300; round++)
            {
                int baseValue = rng.Next(-500, 2000);
                var s = new Stat(baseValue);
                var mods = new System.Collections.Generic.List<Ref>();
                object[] sources = { new Gear("a"), new Gear("a"), new Gear("b"), null };
                var usedIds = new System.Collections.Generic.HashSet<int>();
                for (int step = 0; step < 30; step++)
                {
                    int op = rng.Next(10);
                    if (op < 5 && mods.Count < 10)
                    {
                        var m = new Ref { Kind = rng.Next(2) == 0 ? ModifierKind.Add : ModifierKind.Multiply, Order = rng.Next(-2, 3), Source = sources[rng.Next(4)] };
                        m.Value = m.Kind == ModifierKind.Add ? rng.Next(-50, 51) : rng.Next(-100, 151);
                        m.Id = s.AddModifier(m.Kind, m.Value, m.Order, m.Source);
                        if (m.Id <= 0 || !usedIds.Add(m.Id)) return "라운드 " + round + ": id " + m.Id + " 가 양수가 아니거나 재사용됨";
                        mods.Add(m);
                    }
                    else if (op < 7 && mods.Count > 0)
                    {
                        Ref m = mods[rng.Next(mods.Count)];
                        if (!s.RemoveModifier(m.Id)) return "라운드 " + round + ": 있는 id 제거가 false";
                        mods.Remove(m);
                    }
                    else if (op == 7)
                    {
                        object src = sources[rng.Next(4)];
                        int exp = src == null ? 0 : mods.RemoveAll(m => ReferenceEquals(m.Source, src));
                        int got = s.RemoveAllFromSource(src);
                        if (got != exp) return "라운드 " + round + ": RemoveAllFromSource 기대 " + exp + ", 결과 " + got;
                    }
                    else if (op == 8) { baseValue = rng.Next(-500, 2000); s.BaseValue = baseValue; }
                    long want = RefValue(baseValue, mods);
                    if (s.Value != want || s.ModifierCount != mods.Count)
                    {
                        var desc = new System.Collections.Generic.List<string>();
                        foreach (Ref m in mods) desc.Add((m.Kind == ModifierKind.Add ? "+" : "%") + m.Value + "@" + m.Order);
                        return "라운드 " + round + ": 기본 " + baseValue + ", 추가 순서대로 [" + string.Join(" ", desc) + "] 기대 " + want + ", 결과 " + s.Value;
                    }
                }
            }
            return null;
        });
    }
}

