using System;
using System.Collections.Generic;

// ----- 완성되어 있습니다. 수정하지 마세요. -----

// 지형 "종류" 하나의 정의. 만든 뒤에는 바뀌지 않으며, 같은 종류의 모든 타일이 이 객체 하나를 함께 쓴다.
public sealed class TerrainDef
{
    public string Name { get; }
    public int MoveCost { get; }
    public bool IsWater { get; }

    public TerrainDef(string name, int moveCost, bool isWater)
    {
        Name = name; MoveCost = moveCost; IsWater = isWater;
    }
}

// 지형 정의를 이름당 하나씩만 만들어 보관한다.
public sealed class TerrainCatalog
{
    private readonly Dictionary<string, TerrainDef> _defs = new Dictionary<string, TerrainDef>(StringComparer.Ordinal);

    public int Count
    {
        get { return _defs.Count; }
    }

    public TerrainDef Define(string name, int moveCost, bool isWater)
    {
        if (_defs.ContainsKey(name)) throw new ArgumentException("이미 정의된 지형: " + name, nameof(name));
        TerrainDef def = new TerrainDef(name, moveCost, isWater);   // 정의 객체가 만들어지는 유일한 곳
        _defs.Add(name, def);
        return def;
    }

    public TerrainDef Get(string name)
    {
        TerrainDef def;
        if (!_defs.TryGetValue(name, out def)) throw new KeyNotFoundException("정의되지 않은 지형: " + name);
        return def;
    }
}

public sealed class TileMap
{
    // 공유 상태(지형 정의)는 참조만 들고, 칸마다 다른 상태(잔해)만 칸 수만큼 따로 둔다.
    private readonly TerrainDef[] _terrain;
    private readonly int[] _rubble;

    public int Width { get; }
    public int Height { get; }

    public TileMap(int width, int height, TerrainDef fill)
    {
        Width = width; Height = height;
        _terrain = new TerrainDef[width * height];
        _rubble = new int[width * height];
        for (int i = 0; i < _terrain.Length; i++) _terrain[i] = fill;   // 참조 복사일 뿐 새 객체를 만들지 않는다
    }

    // 1차원 인덱스로 바꾸면 x 가 범위를 벗어나도 옆 줄의 칸을 가리킬 수 있으므로 x, y 를 각각 검사한다.
    private int Index(int x, int y)
    {
        if (x < 0 || x >= Width) throw new ArgumentOutOfRangeException(nameof(x));
        if (y < 0 || y >= Height) throw new ArgumentOutOfRangeException(nameof(y));
        return y * Width + x;
    }

    public TerrainDef GetTerrain(int x, int y)
    {
        return _terrain[Index(x, y)];
    }

    public void SetTerrain(int x, int y, TerrainDef terrain)
    {
        _terrain[Index(x, y)] = terrain;
    }

    public int GetRubble(int x, int y)
    {
        return _rubble[Index(x, y)];
    }

    public void AddRubble(int x, int y, int amount)
    {
        _rubble[Index(x, y)] += amount;
    }

    public int GetMoveCost(int x, int y)
    {
        int i = Index(x, y);
        return _terrain[i].MoveCost + _rubble[i];
    }
}

