{{USER_CODE}}

public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string Thrown(System.Action a)
    {
        try { a(); } catch (System.Exception ex) { return ex.GetType().Name; }
        return "없음";
    }

    public static void Main()
    {
        Run("catalog-one-instance-per-name", () =>
        {
            var cat = new TerrainCatalog();
            if (cat.Count != 0) return "새 카탈로그의 Count 는 0 이어야 함";
            TerrainDef grass = cat.Define("grass", 1, false);
            TerrainDef river = cat.Define("river", 3, true);
            if (grass == null || grass.Name != "grass" || grass.MoveCost != 1 || grass.IsWater) return "Define 이 돌려준 정의의 값이 인자와 다름";
            if (river.MoveCost != 3 || !river.IsWater) return "river 정의의 값이 인자와 다름";
            if (cat.Count != 2) return "두 개를 정의한 뒤 Count 기대 2, 결과 " + cat.Count;
            if (!ReferenceEquals(cat.Get("grass"), grass) || !ReferenceEquals(cat.Get("grass"), cat.Get("grass"))) return "Get(\"grass\") 는 Define 이 만든 바로 그 객체를 매번 돌려줘야 함";
            return ReferenceEquals(cat.Get("river"), river) ? null : "Get(\"river\") 가 다른 객체를 돌려줌";
        });

        Run("catalog-errors", () =>
        {
            var cat = new TerrainCatalog();
            TerrainDef grass = cat.Define("grass", 1, false);
            string t = Thrown(() => cat.Define("grass", 9, true));
            if (t != "ArgumentException") return "같은 이름을 다시 Define: 기대 ArgumentException, 결과 " + t;
            if (cat.Count != 1 || !ReferenceEquals(cat.Get("grass"), grass) || cat.Get("grass").MoveCost != 1) return "실패한 Define 이 기존 정의를 바꿈";
            t = Thrown(() => cat.Get("lava"));
            if (t != "KeyNotFoundException") return "없는 이름의 Get: 기대 KeyNotFoundException, 결과 " + t;
            var other = new TerrainCatalog();
            return other.Count == 0 && Thrown(() => other.Get("grass")) == "KeyNotFoundException" ? null : "카탈로그끼리 정의를 공유하면 안 됨 (static 저장소?)";
        });

        Run("map-shares-definition", () =>
        {
            var cat = new TerrainCatalog();
            TerrainDef grass = cat.Define("grass", 1, false);
            var map = new TileMap(60, 40, grass);
            if (map.Width != 60 || map.Height != 40) return "Width / Height 가 생성자 인자와 다름";
            for (int y = 0; y < 40; y++)
                for (int x = 0; x < 60; x++)
                    if (!ReferenceEquals(map.GetTerrain(x, y), grass)) return "(" + x + "," + y + ") 칸이 fill 로 넘긴 객체가 아닌 다른 객체(복사본?)를 가리킴";
            return cat.Count == 1 ? null : "맵을 만들었는데 카탈로그의 정의 수가 바뀜";
        });

        Run("set-terrain-keeps-rubble", () =>
        {
            var cat = new TerrainCatalog();
            TerrainDef grass = cat.Define("grass", 1, false), hill = cat.Define("hill", 3, false);
            var map = new TileMap(4, 3, grass);
            map.AddRubble(3, 2, 5);
            map.SetTerrain(3, 2, hill);
            if (!ReferenceEquals(map.GetTerrain(3, 2), hill)) return "SetTerrain 뒤 GetTerrain 이 넘긴 객체를 돌려주지 않음";
            if (map.GetRubble(3, 2) != 5) return "SetTerrain 은 잔해를 그대로 둬야 함: 기대 5, 결과 " + map.GetRubble(3, 2);
            if (map.GetMoveCost(3, 2) != 8) return "hill(3) + 잔해 5: 이동 비용 기대 8, 결과 " + map.GetMoveCost(3, 2);
            if (!ReferenceEquals(map.GetTerrain(2, 2), grass) || !ReferenceEquals(map.GetTerrain(3, 1), grass) || !ReferenceEquals(map.GetTerrain(0, 0), grass)) return "한 칸의 SetTerrain 이 다른 칸의 지형을 바꿈";
            return null;
        });

        Run("rubble-is-per-tile", () =>
        {
            var grass = new TerrainCatalog().Define("grass", 2, false);
            var map = new TileMap(5, 4, grass);
            if (map.GetRubble(1, 1) != 0 || map.GetMoveCost(1, 1) != 2) return "처음에는 잔해 0, 이동 비용 = MoveCost 여야 함";
            map.AddRubble(1, 2, 4); map.AddRubble(1, 2, 3); map.AddRubble(4, 3, 1);
            if (map.GetRubble(1, 2) != 7 || map.GetMoveCost(1, 2) != 9) return "(1,2) 에 잔해 4 + 3: 기대 잔해 7 / 비용 9, 결과 " + map.GetRubble(1, 2) + " / " + map.GetMoveCost(1, 2);
            int others = 0;
            for (int y = 0; y < 4; y++) for (int x = 0; x < 5; x++) if (!(x == 1 && y == 2)) others += map.GetRubble(x, y);
            if (others != 1) return "한 칸의 잔해가 다른 칸에 샘 (다른 칸 잔해 합 기대 1, 결과 " + others + ")";
            var map2 = new TileMap(5, 4, grass);
            return map2.GetRubble(1, 2) == 0 && grass.MoveCost == 2 ? null : "같은 정의를 쓰는 다른 맵에 잔해가 보이거나 정의가 바뀜";
        });

        Run("out-of-range", () =>
        {
            var grass = new TerrainCatalog().Define("grass", 1, false);
            var map = new TileMap(5, 4, grass);
            int[][] bad = { new[] { 5, 0 }, new[] { -1, 0 }, new[] { 0, 4 }, new[] { 0, -1 }, new[] { 5, 3 } };
            foreach (int[] p in bad)
            {
                string at = "(" + p[0] + "," + p[1] + ")";
                string t = Thrown(() => map.GetTerrain(p[0], p[1]));
                if (t != "ArgumentOutOfRangeException") return "5x4 맵에서 GetTerrain" + at + ": 기대 ArgumentOutOfRangeException, 결과 " + t;
                t = Thrown(() => map.AddRubble(p[0], p[1], 1));
                if (t != "ArgumentOutOfRangeException") return "5x4 맵에서 AddRubble" + at + ": 기대 ArgumentOutOfRangeException, 결과 " + t;
                if (Thrown(() => map.GetRubble(p[0], p[1])) != "ArgumentOutOfRangeException" || Thrown(() => map.GetMoveCost(p[0], p[1])) != "ArgumentOutOfRangeException" || Thrown(() => map.SetTerrain(p[0], p[1], grass)) != "ArgumentOutOfRangeException")
                    return "5x4 맵에서 " + at + " 에 대한 GetRubble / GetMoveCost / SetTerrain 은 ArgumentOutOfRangeException 이어야 함";
            }
            int sum = 0;
            for (int y = 0; y < 4; y++) for (int x = 0; x < 5; x++) sum += map.GetRubble(x, y);
            return sum == 0 ? null : "범위 밖 AddRubble 이 맵 안의 다른 칸을 바꿈";
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(99);
            var cat = new TerrainCatalog();
            TerrainDef[] defs = { cat.Define("grass", 1, false), cat.Define("hill", 3, false), cat.Define("river", 2, true), cat.Define("swamp", 4, true) };
            for (int round = 0; round < 40; round++)
            {
                int w = rng.Next(1, 9), h = rng.Next(1, 9);
                var map = new TileMap(w, h, defs[0]);
                var refDef = new int[w, h]; var refRubble = new int[w, h];
                for (int step = 0; step < 200; step++)
                {
                    int x = rng.Next(w), y = rng.Next(h);
                    if (rng.Next(2) == 0) { int d = rng.Next(4); map.SetTerrain(x, y, defs[d]); refDef[x, y] = d; }
                    else { int a = rng.Next(0, 4); map.AddRubble(x, y, a); refRubble[x, y] += a; }
                }
                for (int y = 0; y < h; y++)
                    for (int x = 0; x < w; x++)
                    {
                        TerrainDef want = defs[refDef[x, y]];
                        if (!ReferenceEquals(map.GetTerrain(x, y), want) || map.GetRubble(x, y) != refRubble[x, y] || map.GetMoveCost(x, y) != want.MoveCost + refRubble[x, y])
                            return "라운드 " + round + " (" + w + "x" + h + ") 의 (" + x + "," + y + "): 기대 " + want.Name + " / 잔해 " + refRubble[x, y] + ", 결과 " + map.GetTerrain(x, y).Name + " / 잔해 " + map.GetRubble(x, y) + " / 비용 " + map.GetMoveCost(x, y);
                    }
            }
            return cat.Count == 4 ? null : "카탈로그의 정의 수가 4 가 아님";
        });
    }
}
